// useTelegramBackButton.ts
import { useEffect } from 'react';

// Wires the native Telegram BackButton to a callback.
// Falls back silently when running outside Telegram (e.g. in a browser during dev).
export function useTelegramBackButton(onBack: () => void): void {
  useEffect(() => {
    const tg = (window as any)?.Telegram?.WebApp;
    if (!tg?.BackButton) return;

    tg.BackButton.show();
    tg.BackButton.onClick(onBack);

    return () => {
      tg.BackButton.offClick(onBack);
      tg.BackButton.hide();
    };
  }, [onBack]);
}
