// CheckoutScreen.tsx
import React, { useMemo, useState } from 'react';
import { CartItem, DeliveryAddress, EMPTY_ADDRESS } from './types';
import { useTelegramBackButton } from './useTelegramBackButton';
import './CheckoutScreen.css';

interface CheckoutScreenProps {
  items: CartItem[];
  currencySymbol?: string;
  deliveryFee?: number;
  onBackToCart: () => void;
  onPay: (address: DeliveryAddress, total: number) => void | Promise<void>;
}

type FieldErrors = Partial<Record<keyof DeliveryAddress, string>>;

const REQUIRED_FIELDS: (keyof DeliveryAddress)[] = [
  'fullName',
  'phone',
  'city',
  'street',
  'house',
];

function validate(address: DeliveryAddress): FieldErrors {
  const errors: FieldErrors = {};

  for (const field of REQUIRED_FIELDS) {
    if (!address[field].trim()) {
      errors[field] = 'Required';
    }
  }

  if (address.phone.trim() && !/^\+?[0-9\s()-]{7,20}$/.test(address.phone.trim())) {
    errors.phone = 'Enter a valid phone number';
  }

  return errors;
}

export default function CheckoutScreen({
  items,
  currencySymbol = '$',
  deliveryFee = 0,
  onBackToCart,
  onPay,
}: CheckoutScreenProps) {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<FieldErrors>({});
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});
  const [isPaying, setIsPaying] = useState(false);

  useTelegramBackButton(onBackToCart);

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [items]
  );
  const total = subtotal + deliveryFee;

  const handleChange = (field: keyof DeliveryAddress) => (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) => {
    const value = e.target.value;
    setAddress((prev) => ({ ...prev, [field]: value }));
    if (touched[field]) {
      setErrors((prev) => ({ ...validate({ ...address, [field]: value }) }));
    }
  };

  const handleBlur = (field: keyof DeliveryAddress) => () => {
    setTouched((prev) => ({ ...prev, [field]: true }));
    setErrors(validate(address));
  };

  const handlePay = async () => {
    const validationErrors = validate(address);
    setErrors(validationErrors);
    setTouched(
      REQUIRED_FIELDS.reduce((acc, field) => ({ ...acc, [field]: true }), {})
    );

    if (Object.keys(validationErrors).length > 0) {
      (window as any)?.Telegram?.WebApp?.HapticFeedback?.notificationOccurred('error');
      return;
    }

    try {
      setIsPaying(true);
      await onPay(address, total);
    } finally {
      setIsPaying(false);
    }
  };

  const isFormValid = Object.keys(validate(address)).length === 0;

  return (
    <div className="checkout-screen">
      <header className="checkout-header">
        <button
          type="button"
          className="back-button"
          onClick={onBackToCart}
          aria-label="Back to cart"
        >
          <span className="back-icon" aria-hidden="true">
            &#8592;
          </span>
          Back to cart
        </button>
        <h1 className="checkout-title">Checkout</h1>
      </header>

      <section className="order-summary" aria-label="Order summary">
        <h2 className="section-title">Your order</h2>
        <ul className="cart-list">
          {items.map((item) => (
            <li key={item.id} className="cart-item">
              {item.imageUrl ? (
                <img
                  className="cart-item-image"
                  src={item.imageUrl}
                  alt={item.title}
                />
              ) : (
                <div className="cart-item-image cart-item-image--placeholder" />
              )}
              <div className="cart-item-info">
                <span className="cart-item-title">{item.title}</span>
                <span className="cart-item-qty">Qty: {item.quantity}</span>
              </div>
              <span className="cart-item-price">
                {currencySymbol}
                {(item.price * item.quantity).toFixed(2)}
              </span>
            </li>
          ))}
        </ul>

        <div className="summary-row">
          <span>Subtotal</span>
          <span>
            {currencySymbol}
            {subtotal.toFixed(2)}
          </span>
        </div>
        <div className="summary-row">
          <span>Delivery</span>
          <span>
            {deliveryFee > 0 ? `${currencySymbol}${deliveryFee.toFixed(2)}` : 'Free'}
          </span>
        </div>
        <div className="summary-row summary-row--total">
          <span>Total</span>
          <span>
            {currencySymbol}
            {total.toFixed(2)}
          </span>
        </div>
      </section>

      <section className="delivery-form" aria-label="Delivery address">
        <h2 className="section-title">Delivery address</h2>

        <div className="form-field">
          <label htmlFor="fullName">Full name</label>
          <input
            id="fullName"
            type="text"
            value={address.fullName}
            onChange={handleChange('fullName')}
            onBlur={handleBlur('fullName')}
            className={errors.fullName && touched.fullName ? 'input-error' : ''}
            placeholder="Jane Doe"
          />
          {errors.fullName && touched.fullName && (
            <span className="field-error">{errors.fullName}</span>
          )}
        </div>

        <div className="form-field">
          <label htmlFor="phone">Phone number</label>
          <input
            id="phone"
            type="tel"
            value={address.phone}
            onChange={handleChange('phone')}
            onBlur={handleBlur('phone')}
            className={errors.phone && touched.phone ? 'input-error' : ''}
            placeholder="+1 555 123 4567"
          />
          {errors.phone && touched.phone && (
            <span className="field-error">{errors.phone}</span>
          )}
        </div>

        <div className="form-field">
          <label htmlFor="city">City</label>
          <input
            id="city"
            type="text"
            value={address.city}
            onChange={handleChange('city')}
            onBlur={handleBlur('city')}
            className={errors.city && touched.city ? 'input-error' : ''}
            placeholder="New York"
          />
          {errors.city && touched.city && (
            <span className="field-error">{errors.city}</span>
          )}
        </div>

        <div className="form-row">
          <div className="form-field form-field--grow">
            <label htmlFor="street">Street</label>
            <input
              id="street"
              type="text"
              value={address.street}
              onChange={handleChange('street')}
              onBlur={handleBlur('street')}
              className={errors.street && touched.street ? 'input-error' : ''}
              placeholder="Main St"
            />
            {errors.street && touched.street && (
              <span className="field-error">{errors.street}</span>
            )}
          </div>
          <div className="form-field form-field--small">
            <label htmlFor="house">House</label>
            <input
              id="house"
              type="text"
              value={address.house}
              onChange={handleChange('house')}
              onBlur={handleBlur('house')}
              className={errors.house && touched.house ? 'input-error' : ''}
              placeholder="12"
            />
            {errors.house && touched.house && (
              <span className="field-error">{errors.house}</span>
            )}
          </div>
        </div>

        <div className="form-row">
          <div className="form-field form-field--small">
            <label htmlFor="apartment">Apartment</label>
            <input
              id="apartment"
              type="text"
              value={address.apartment}
              onChange={handleChange('apartment')}
              placeholder="4B"
            />
          </div>
          <div className="form-field form-field--small">
            <label htmlFor="postalCode">Postal code</label>
            <input
              id="postalCode"
              type="text"
              value={address.postalCode}
              onChange={handleChange('postalCode')}
              placeholder="10001"
            />
          </div>
        </div>

        <div className="form-field">
          <label htmlFor="comment">Comment (optional)</label>
          <textarea
            id="comment"
            value={address.comment}
            onChange={handleChange('comment')}
            placeholder="Delivery instructions, entry code, etc."
            rows={3}
          />
        </div>
      </section>

      <div className="checkout-footer">
        <button
          type="button"
          className="pay-button"
          onClick={handlePay}
          disabled={isPaying}
        >
          {isPaying
            ? 'Processing…'
            : `Pay ${currencySymbol}${total.toFixed(2)}`}
        </button>
        {!isFormValid && (
          <p className="footer-hint">Fill in the required address fields to continue.</p>
        )}
      </div>
    </div>
  );
}
```

